3	/**
4	 * Client-side plumbing for feature flags.
5	 *
6	 * The server evaluates every flag once per request with `snapshotFlags()` and
7	 * serialises the result into `FeatureFlagProvider`. The client therefore reads
8	 * the snapshot rather than re-deriving anything — but when a key is missing
9	 * (a snapshot serialised before a newly shipped flag existed) we fall back to
10	 * `isEnabled()` so there is still exactly one evaluator in the codebase.
11	 */
12	import { createContext } from "react";
13	import { isEnabled } from "@/lib/feature-flags";
14	import type {
15	  FeatureFlagKey,
16	  FeatureFlagSnapshot,
17	  FlagContext,
18	} from "@/types/feature-flag";
